<?php
$root=dirname(__DIR__);$env=@parse_ini_file($root.'/.env',false,INI_SCANNER_RAW)?:[];$dsn='mysql:host='.($env['DB_HOST']??'127.0.0.1').';port='.($env['DB_PORT']??'3306').';dbname='.($env['DB_DATABASE']??'zynko').';charset=utf8mb4';$pdo=new PDO($dsn,$env['DB_USERNAME']??'root',$env['DB_PASSWORD']??'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);require_once $root.'/app/Services/InboundEmailService.php';$svc=new InboundEmailService($pdo,$root);$rows=$pdo->query("SELECT DISTINCT tenant_id FROM correo WHERE is_default=1 AND inbound_enabled=1 AND inbound_method<>'NONE'")->fetchAll(PDO::FETCH_COLUMN);$errors=0;foreach($rows as $tid){try{$r=$svc->pollTenant((int)$tid);echo '['.date('c').'] tenant='.$tid.' '.$r['message'].PHP_EOL;if(!$r['ok'])$errors++;}catch(Throwable $e){$errors++;fwrite(STDERR,'tenant='.$tid.' ERROR '.$e->getMessage().PHP_EOL);}}exit($errors?1:0);
